"use strict";
/* Homepage enhancements. The roadmap is plain HTML (generated by tools/make_index.py);
   this script only adds search/filter and the small Fibonacci demo. */
(() => {
  const $ = s => document.querySelector(s);

  // Roadmap filter
  const filters = $("#filters"), search = $("#search"), filter = $("#module-filter"),
        count = $("#result-count"), empty = $("#catalog-empty");
  const modules = [...document.querySelectorAll("#catalog .module")];
  const total = document.querySelectorAll("#catalog .lesson").length;
  if (filters && modules.length) {
    filters.hidden = false;
    const openByDefault = new Map(modules.map(m => [m, m.open]));
    const apply = () => {
      const q = search.value.toLowerCase().trim(), sel = filter.value;
      let shown = 0;
      modules.forEach(m => {
        const inModule = sel === "all" || sel === m.dataset.module;
        let hits = 0;
        m.querySelectorAll(".lesson").forEach(li => {
          const ok = inModule && (!q || li.dataset.search.includes(q));
          li.hidden = !ok;
          if (ok) hits++;
        });
        m.hidden = hits === 0;
        m.open = (q || sel !== "all") ? hits > 0 : openByDefault.get(m);
        shown += hits;
      });
      count.textContent = (q || sel !== "all") ? `${shown} of ${total} lectures` : "";
      empty.hidden = shown !== 0;
    };
    search.addEventListener("input", apply);
    filter.addEventListener("change", apply);
  }

  // Fibonacci table demo
  const cells = $("#cells");
  if (!cells) return;
  const values = [0, 1, 1, 2, 3, 5], last = values.length - 1;
  const msg = $("#demo-status"), prev = $("#prev"), next = $("#next"), play = $("#play"), reset = $("#reset");
  let step = 0, timer = null;
  const el = (tag, cls, text) => { const n = document.createElement(tag); if (cls) n.className = cls; if (text !== undefined) n.textContent = text; return n; };
  const stop = () => { if (timer !== null) { clearInterval(timer); timer = null; } play.textContent = "Play"; play.setAttribute("aria-pressed", "false"); };
  const show = () => {
    cells.replaceChildren(...values.map((v, i) => {
      const c = el("div", "cell " + (i === step ? "current" : i < step ? "done" : ""));
      c.append(el("small", "", `F(${i})`), el("strong", "", i <= step ? String(v) : "—"));
      return c;
    }));
    msg.textContent = step < 2 ? `Base case: F(${step}) = ${values[step]}.`
      : `F(${step}) = F(${step - 1}) + F(${step - 2}) = ${values[step - 1]} + ${values[step - 2]} = ${values[step]}.`;
    prev.disabled = step === 0; next.disabled = step === last;
    if (step === last) stop();
  };
  prev.addEventListener("click", () => { stop(); step = Math.max(0, step - 1); show(); });
  next.addEventListener("click", () => { stop(); step = Math.min(last, step + 1); show(); });
  reset.addEventListener("click", () => { stop(); step = 0; show(); });
  play.addEventListener("click", () => {
    if (timer !== null) { stop(); return; }
    if (step === last) { step = 0; show(); }
    play.textContent = "Pause"; play.setAttribute("aria-pressed", "true");
    timer = setInterval(() => { step = Math.min(last, step + 1); show(); }, 1000);
  });
  show();
})();
